134	import java.math.BigDecimal;
135	import java.math.RoundingMode;
136	import java.time.LocalDate;
137	import java.time.Month;
138	
139	/**
140	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
141	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
142	 * (half-even) at every step.
143	 */
144	public final class PriceCalculator {
145	
146	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
147	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
148	
149	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
150	        int nights = 0;
151	        BigDecimal subtotal = cents(BigDecimal.ZERO);
152	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
153	            subtotal = subtotal.add(nightPrice(room, night));
154	            nights++;
155	        }
156	        BigDecimal discount = switch (ratePlan) {
157	            case STANDARD -> cents(BigDecimal.ZERO);
158	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
159	        };
160	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
161	    }
162	
163	    BigDecimal nightPrice(Room room, LocalDate night) {
164	        BigDecimal nightlyRate = room.nightlyRate();
165	        if (isHighSeason(night)) {
166	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
167	        }
168	        return cents(nightlyRate);
169	    }
170	
171	    /** High season: from December 15 to the end of February, and the whole of July. */
172	    static boolean isHighSeason(LocalDate date) {
173	        Month month = date.getMonth();
174	        return month == Month.JANUARY
175	                || month == Month.FEBRUARY
176	                || month == Month.JULY
177	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
178	    }
179	
180	    static BigDecimal cents(BigDecimal value) {
181	        return value.setScale(2, RoundingMode.HALF_EVEN);
182	    }
183	}

